svg.script:
(() => {
  function applyState(state) {
    if (!state || state.type !== "simurep-synoptic-state") return;
    Object.entries(state.values || {}).forEach(([id, value]) => {
      const node = document.getElementById(id);
      if (node) node.textContent = value;
    });
    document.querySelectorAll("[data-signal]").forEach(node => {
      node.classList.remove("alarm-warning", "alarm-danger");
      const level = (state.alarmLevels || {})[node.dataset.signal];
      if (level) node.classList.add(`alarm-${level}`);
    });
    const level = Math.max(0, Math.min(100, Number(state.level) || 0));
    const liquidHeight = 188 * level / 100;
    const liquidY = 429 - liquidHeight;
    const liquid = document.getElementById("pressLiquid");
    const levelLine = document.getElementById("pressLevelLine");
    if (liquid) {
      liquid.setAttribute("y", liquidY.toFixed(2));
      liquid.setAttribute("height", liquidHeight.toFixed(2));
    }
    if (levelLine) {
      levelLine.setAttribute("d", `M331 ${liquidY.toFixed(2)} H439`);
      levelLine.style.display = level <= 0 ? "none" : "";
    }
    const heater = document.getElementById("heaterCoil");
    if (heater) heater.style.opacity = String(0.25 + 0.75 * (Number(state.heaterImmersion) || 0));
    const rods = document.getElementById("controlRods");
    if (rods) {
      const position = Math.max(0, Math.min(100, Number(state.rods) || 0));
      rods.style.transform = `translateY(${(0.75 * position).toFixed(2)}px)`;
    }
    document.querySelectorAll(".spray-jet").forEach(node => {
      node.style.opacity = state.sprayOpen ? "1" : "0.18";
    });
    const reliefLine = document.getElementById("reliefLine");
    const reliefValve = document.getElementById("reliefValveSymbol");
    if (reliefLine) reliefLine.classList.toggle("active", Boolean(state.reliefOpen));
    if (reliefValve) reliefValve.classList.toggle("valve-active", Boolean(state.reliefOpen));
  }

  window.addEventListener("message", event => applyState(event.data));
  const announceReady = () => parent.postMessage({ type: "simurep-synoptic-ready" }, "*");
  announceReady();
  setTimeout(announceReady, 250);
  setTimeout(announceReady, 1000);
})();
